 public function create(string $publicToken,string $provider,array $options=[]):array{
  $provider=strtolower(trim($provider));if(!in_array($provider,['stripe','mercadopago','pagbank'],true))throw new RuntimeException('Provedor inválido.');$method=strtolower((string)($options['payment_method']??'checkout'));$document=preg_replace('/\D+/','',(string)($options['payer_document']??''))??'';
  $pdo=Database::connection();$s=$pdo->prepare('SELECT o.*,t.slug tenant_slug,t.status tenant_status,c.name customer_name,c.email customer_email,c.phone customer_phone FROM orders o JOIN tenants t ON t.id=o.tenant_id LEFT JOIN customers c ON c.id=o.customer_id WHERE o.public_token=? LIMIT 1');$s->execute([$publicToken]);$order=$s->fetch();if(!$order||$order['tenant_status']!=='active')throw new RuntimeException('Pedido não encontrado.');if(in_array($order['status'],['cancelled','completed'],true)||$order['payment_status']==='paid')throw new RuntimeException('Pedido não aceita nova cobrança.');if((int)$order['total_cents']<=0)throw new RuntimeException('Pedido com valor inválido.');if($method==='pix'&&!in_array(strlen($document),[11,14],true))throw new RuntimeException('CPF/CNPJ obrigatório para Pix.');
