 private function mercadoPagoPix(array$o,array$c,string$key,string$doc):array{$token=(string)($c['access_token']??'');if($token==='')throw new RuntimeException('Mercado Pago não configurado.');$type=strlen($doc)===11?'CPF':'CNPJ';$body=['transaction_amount'=>((int)$o['total_cents'])/100,'description'=>'Pedido EventMenu #'.$o['id'],'payment_method_id'=>'pix','external_reference'=>'eventmenu:'.$o['tenant_id'].':'.$o['id'],'payer'=>['email'=>$o['customer_email']?:'cliente@eventmenu.local','identification'=>['type'=>$type,'number'=>$doc]],'notification_url'=>\app_absolute_url('webhook.php?provider=mercadopago&tenant='.rawurlencode($o['tenant_slug']))];$d=$this->httpJson('POST','https://api.mercadopago.com/v1/payments',['Authorization: Bearer '.$token,'X-Idempotency-Key: '.$key],$body);$tx=$d['point_of_interaction']['transaction_data']??[];return['url'=>(string)($tx['ticket_url']??''),'qr_code'=>(string)($tx['qr_code']??''),'qr_code_base64'=>(string)($tx['qr_code_base64']??''),'external_id'=>(string)($d['id']??''),'raw'=>$d];}
 private function mercadoPago(array$o,array$g,array$c,string$key):array{$token=(string)($c['access_token']??'');if($token==='')throw new RuntimeException('Mercado Pago não configurado.');$ret=\app_absolute_url('pedido.php?t='.rawurlencode($o['public_token']));$b=['items'=>[['title'=>'Pedido EventMenu #'.$o['id'],'quantity'=>1,'currency_id'=>'BRL','unit_price'=>((int)$o['total_cents'])/100]],'external_reference'=>'eventmenu:'.$o['tenant_id'].':'.$o['id'],'back_urls'=>['success'=>$ret,'pending'=>$ret,'failure'=>$ret],'notification_url'=>\app_absolute_url('webhook.php?provider=mercadopago&tenant='.rawurlencode($o['tenant_slug']))];$d=$this->httpJson('POST','https://api.mercadopago.com/checkout/preferences',['Authorization: Bearer '.$token,'X-Idempotency-Key: '.$key],$b);return['url'=>(string)($d['init_point']??''),'external_id'=>(string)($d['id']??''),'raw'=>$d];}
 private function pagBank(array$o,array$c,string$key,string$method):array{$token=(string)($c['token']??'');if($token==='')throw new RuntimeException('PagBank não configurado.');$api=rtrim((string)($c['api_base']??'https://api.pagseguro.com'),'/');$methods=$method==='pix'?[['type'=>'PIX']]:[['type'=>'CREDIT_CARD'],['type'=>'PIX']];$ret=\app_absolute_url('pedido.php?t='.rawurlencode($o['public_token']));$b=['reference_id'=>'eventmenu:'.$o['tenant_id'].':'.$o['id'],'items'=>[['name'=>'Pedido EventMenu #'.$o['id'],'quantity'=>1,'unit_amount'=>(int)$o['total_cents']]],'payment_methods'=>$methods,'redirect_url'=>$ret,'return_url'=>$ret,'notification_urls'=>[\app_absolute_url('webhook.php?provider=pagbank&tenant='.rawurlencode($o['tenant_slug']))]];$d=$this->httpJson('POST',$api.'/checkouts',['Authorization: Bearer '.$token,'x-idempotency-key: '.$key],$b);$url='';foreach(($d['links']??[])as$l)if(($l['rel']??'')==='PAY'){$url=(string)$l['href'];break;}return['url'=>$url,'external_id'=>(string)($d['id']??''),'raw'=>$d];}
 private function stripe(array$o,array$g,array$c,string$key):array{throw new RuntimeException('Stripe permanece disponível pelo checkout padrão; Pix não é processado pelo Stripe neste fluxo.');}
 private function httpJson(string$m,string$u,array$h,array$b):array{$ch=curl_init($u);if($ch===false)throw new RuntimeException('Falha HTTP.');$h[]='Accept: application/json';$h[]='Content-Type: application/json';curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>$h,CURLOPT_POSTFIELDS=>json_encode($b,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>25,CURLOPT_SSL_VERIFYPEER=>true]);$r=curl_exec($ch);$s=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($r===false||$s<200||$s>=300)throw new RuntimeException('Gateway recusou a cobrança (HTTP '.$s.').');$d=json_decode((string)$r,true,512,JSON_THROW_ON_ERROR);if(!is_array($d))throw new RuntimeException('Resposta inválida do gateway.');return$d;}
}
